static int32_t sms_del_rev_read_file_check(const char * path)
{
    int32_t         ret;
    FILE *          p_file;

    p_file              = fopen(path,"rb");

    ret                 = -1;

    if (p_file != NULL) {
        size_t          read_len;
        tele_sms_storge_rev_param_t sms_sim_resp;

        read_len = sizeof(tele_sms_storge_rev_param_t)-4;
        fread(&sms_sim_resp,1,read_len,p_file);

        fclose(p_file);

        __inf("sms_sim_resp.base_info.err_code: %d\n",sms_sim_resp.param.base_info.err_code);

        if(sms_sim_resp.param.base_info.err_code==1) {
            /* remove a file object */
            if (unlink(path) == 0) {
                __inf("app_fs_remove_folder: Removed a file: %s\n",path);
                ret                 = 0;
                }
            else {
                __inf("app_fs_remove_folder: Can`t remove a file: %s\n",path);
                }
            }

        }

    return ret;
}


void sms_del_rev_read_file(const char * path)
{
    size_t          path_len;
    char *          full_path;
    DIR *           dir;

    struct stat stat_entry;
    struct dirent * entry;
    int32_t         result = 1;


    if ((dir = opendir(path)) == NULL) {
        __inf("app_fs_remove_folder: unable to opendir %s\n",path);
        return;
        }

    /* the length of the path */
    path_len            = strlen(path);

    /* iteration through entries in the directory */
    while ((entry = readdir(dir)) != NULL) {
        /* skip entries "." and ".." */
        if (!strcmp(entry->d_name,".") || !strcmp(entry->d_name,".."))
            continue;

        /* determinate a full path of an entry */
        full_path           = lv_mem_alloc(path_len + strlen(entry->d_name) + 2);

        if (full_path) {
            strcpy(full_path,path);
            strcat(full_path,"/");
            strcat(full_path,entry->d_name);

            /* stat for the entry */
            if (-1 != stat(full_path,&stat_entry)) {
                /* recursively remove a nested directory */
                if (S_ISDIR(stat_entry.st_mode) != 0) {
                    result              = fp_fs_remove_folder(full_path);
                    }
                else {
                    if (0 == sms_del_rev_read_file_check(full_path))
                        sms_data_box_count_reduce((uint8_t *)path);
                    }
                }

            lv_mem_free(full_path);

            if (!result) {
                break;
                }
            }
        else {
            result              = 0;
            __inf("app_fs_remove_folder: no memory\n");
            break;
            }
        }

    closedir(dir);
}


